    def get_prime_factors(x):
        factors = {}
        d = 2
        temp = x
        while d * d <= temp and d <= 1000000:
            if temp % d == 0:
                while temp % d == 0:
                    factors[d] = factors.get(d, 0) + 1
                    temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

