    def C(n, k):
        """Binomial coefficient C(n, k) mod p"""
        if k < 0 or k > n:
            return 0
        return math.comb(n, k) % p

    def count_for_balance(n, p, final_balance):
        """Count valid queues with final 50-yuan notes = final_balance"""
        count = 0

        for s in range(0, n + 1):  # s = a + b (non-C customers)
            if s < abs(final_balance):
                continue
            if (s - final_balance) % 2 != 0:
                continue

            a = (s + final_balance) // 2  # number of type A (50-yuan)
            b = (s - final_balance) // 2  # number of type B (100-yuan)
            c = n - s                      # number of type C (VIP)

            if a < 0 or b < 0 or c < 0:
                continue

            # Valid (A,B) sequences without going negative: 
            # Ballot theorem: C(a+b, b) - C(a+b, b-1)
            valid_ab = C(a + b, b) - C(a + b, b - 1)

            # Ways to choose positions for C among n total positions
            ways_c = C(n, c)

            if valid_ab > 0 and ways_c > 0:
                count = (count + valid_ab * ways_c) % p

        return count

    # Sum over all valid final balances in [l, r]
    ans = 0
    for target in range(max(0, l), min(r, n) + 1):
        ans = (ans + count_for_balance(n, p, target)) % p

    return str(ans)

