    visited = [False] * n_nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for u in range(n_nodes):
        if not visited[u]:
            dfs1(u)

    reverse_adj = [[] for _ in range(n_nodes)]
    for u in range(n_nodes):
        for v in adj[u]:
            reverse_adj[v].append(u)

    scc_id = [-1] * n_nodes
    scc_count = 0
    visited2 = [False] * n_nodes

    def dfs2(u):
        visited2[u] = True
        scc_id[u] = scc_count
        for v in reverse_adj[u]:
            if not visited2[v]:
                dfs2(v)

    for u in reversed(order):
        if not visited2[u]:
            dfs2(u)
            scc_count += 1

    # Check for contradictions
    for i in range(m):
        idx0 = 2 * i  # x_i
        idx1 = 2 * i + 1  # ¬x_i
        if scc_id[idx0] == scc_id[idx1]:
            return "NO\n"

    # Build assignment from SCC structure
    # If no path from ¬x_i to x_i, set x_i to True
    reachable = [False] * n_nodes

    def can_reach(u, target):
        q = [u]
        visited = {u}
        while q:
            curr = q.pop(0)
            if curr == target:
                return True
            for v in adj[curr]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        return False

    assignment_vars = [[False, False] for _ in range(m)]

    for i in range(m):
        idx0 = 2 * i  # x_i is True
        idx1 = 2 * i + 1  # x_i is False

        can_set_true = can_reach(idx1, idx0)  # Can ¬x_i reach x_i? If so, x_i must be False
        can_set_false = can_reach(idx0, idx1)  # Can x_i reach ¬x_i? If so, x_i must be True

        if can_set_true and can_set_false:
            # Both paths exist, return any valid (via SCC, they have same id)
            assignment_vars[i][0] = True
            assignment_vars[i][1] = False
        elif can_set_true:
            assignment_vars[i][0] = False
            assignment_vars[i][1] = True
        elif can_set_false:
            assignment_vars[i][0] = True
            assignment_vars[i][1] = False
        else:
            assignment_vars[i][0] = True
            assignment_vars[i][1] = False

    # Construct final assignment (pick True or False for each variable)
    assignment_str = ''.join('1' if assignment_vars[i][0] else '0' for i in range(m))

    return "YES\n" + assignment_str

