import math

def solution(data):
    lines = data.strip().split('\n')

    # Parse first line: n, w, v, u
    first_parts = lines[0].split()
    n = int(first_parts[0])
    w = int(first_parts[1])
    v = int(first_parts[2])
    u = int(first_parts[3])

    # Parse polygon vertices
    polygon = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        polygon.append((int(parts[0]), int(parts[1])))

    def get_shifted(t):
        return [(x - v * t, y) for x, y in polygon]

    def is_point_strictly_inside(px, py, pts):
        if len(pts) == 0:
            return False

        wn = 0
        for i in range(len(pts)):
            xj, yj = pts[(i + 1) % len(pts)]
            xi, yi = pts[i]
            if ((yi > py) != (yj > py)):
                x_int = xi + (py - yi) * (xj - xi) / (yj - yi)
                if px < x_int:
                    wn += 1
        return wn % 2 == 1

    def can_cross_in_time(T):
        max_dist = u * T
        if max_dist < w - 1e-9:
            return False

        for i in range(1, 5000):
            t = T * i / 5000.0
            y_at_t = min(w, u * t)
            if is_point_strictly_inside(0, y_at_t, get_shifted(t)):
                return False
        return True

    low, high = 0.0, 2e10
    for _ in range(100):
        mid = (low + high) / 2
        if can_cross_in_time(mid):
            high = mid
        else:
            low = mid

    return f"{high:.10f}"

