    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    def count_trailing_zeros(num):
        return min(count_2(num), count_2(num))

    def count_2(n):
        c = 0
        while n > 0 and n % 2 == 0:
            c += 1
            n //= 2
        return c

    def count_5(n):
        c = 0
        while n > 0 and n % 5 == 0:
            c += 1
            n //= 5
        return c

    # dp[r][c] = list of (count2, count5, path)
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Start
    val = matrix[0][0]
    c2 = count_2(val) if val > 0 else 0
    c5 = count_5(val) if val > 0 else 0
    dp[0][0].append((c2, c5, ''))

    for r in range(n):
        for c in range(n):
            if r == 0 and c == 0:
                continue

            val = matrix[r][c]
            add2 = count_2(val) if val > 0 else 0
            add5 = count_5(val) if val > 0 else 0

            candidates = []
            # From top
            if r > 0:
                for (s2, s5, p) in dp[r-1][c]:
                    candidates.append((s2+add2, s5+add5, p+'D'))
            # From left  
            if c > 0:
                for (s2, s5, p) in dp[r][c-1]:
                    candidates.append((s2+add2, s5+add5, p+'R'))

            # Keep best for each (count2, count5)
            d = {}
            for (k2, k5, p) in candidates:
                if (k2, k5) not in d or len(p) < len(d[(k2, k5)]):
                    d[(k2, k5)] = p
            dp[r][c] = list(d.values())

    best = None
    for (s2, s5, p) in dp[n-1][n-1]:
        zeros = min(s2, s5)
        if best is None or zeros < best[0]:
            best = (zeros, p)

    return f"{best[0]}\n{best[1]}"


