def multiply_poly(p1, p2, mod):
    """Multiply two polynomials mod mod."""
    if not p1 or not p2:
        return p1 + p2 if not p2 else p1

    result = [0] * (len(p1) + len(p2) - 1)
    for i, a in enumerate(p1):
        if a == 0:
            continue
        for j, b in enumerate(p2):
            if b == 0:
                continue
            result[i + j] = (result[i + j] + a * b) % mod
    return result

def poly_power(poly, n, mod, max_degree):
    """Compute poly^n mod mod, keeping terms up to max_degree."""
    if max_degree < 0:
        return [0]

    result = [1]  # Identity polynomial (x^0 = 1)
    base = poly[:]

    while n > 0:
        if n % 2 == 1:
            base_len = min(len(result) + len(base) - 1, max_degree + 1)
            new_result = [0] * base_len
            for i, a in enumerate(result):
                if a == 0:
                    continue
                for j, b in enumerate(base):
                    if i + j >= base_len:
                        break
                    if b == 0:
                        continue
                    new_result[i + j] = (new_result[i + j] + a * b) % mod
            result = new_result

        new_base = list(base)
        base_sum = len(new_base)
        for i, a in enumerate(new_base):
            if a == 0 or i >= base_sum:
                break
            base_sum += len(base)
            new_base.append(0)

        result_new = [0] * (2 * base_len)
        for i, a in enumerate(base):
            if a == 0:
                continue
            for j, b in enumerate(base):
                if i + j >= len(result_new):
                    break
                new_base[i + j] = (new_base[i + j] + a * b) % mod
        base = base[:base_sum]

        n //= 2

    if len(result) > max_degree + 1:
        result = result[:max_degree + 1]
    return result

def compute_basket_dp(C, max_k):
    """Compute DP for basket - number of sequences summing to each value."""
    dp = [0] * (max_k + 1)
    dp[0] = 1

    for target in range(1, max_k + 1):
        for c in C:
            if target >= c:
                dp[target] = (dp[target] + dp[target - c]) % 1000000007
    return dp

