from functools import lru_cache

sys.setrecursionlimit(10000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n <= 1:
        return str(n) + '\n'

    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Build tree structure using BFS (rooted at node 1)
    children = [[] for _ in range(n + 1)]
    visited = [False] * (n + 1)
    queue = [1]
    visited[1] = True

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                children[u].append(v)
                queue.append(v)

    @lru_cache(maxsize=None)
    def solve(u):
        # Returns {component_size: max_product_in_subtree} assuming u's component has that size
        if not children[u]:
            return {1: 1}

        res = {1: 1}

        for v in children[u]:
            child_res = solve(v)
            new_res = {}

            for size_u, prod_u in res.items():
                for size_v, prod_v in child_res.items():
                    # Option 1: Cut edge to v
                    # u's component stays size_u, v's subtree contributes size_v to product
                    cut_size = size_u
                    cut_prod = prod_u * prod_v * size_v
                    new_res[cut_size] = max(new_res.get(cut_size, 0), cut_prod)

                    # Option 2: Keep edge to v (merge)
                    # Merged component has size_u + size_v
                    merge_size = size_u + size_v
                    merge_prod = prod_u * prod_v
                    new_res[merge_size] = max(new_res.get(merge_size, 0), merge_prod)

            res = new_res

        return res

    final_ans = 0
    for size_u, prod_u in solve(1).items():
        final_ans = max(final_ans, size_u * prod_u)

    return str(final_ans) + '\n'

def solution(input_string):
    input_string = input_string.strip()
