    if len(lines) < 1:
        return '0\n'

    first_line = lines[0].split()
    if len(first_line) < 2:
        return '0\n'

    n, m = int(first_line[0]), int(first_line[1])

    if n * m == 0:
        return '0\n'

    grid = []
    for i in range(n):
        row = []
        line = lines[i + 1] if i + 1 < len(lines) else ''
        for j in range(m):
            if j < len(line):
                ch = line[j]
            else:
                ch = '.'
            if ch == '.':
                row.append(0)
            elif ch in '1234':
                row.append(int(ch))
            else:
                row.append(0)
        grid.append(row)

    MOD = 1000003

    def get_directions(p_type):
        """Returns the set of direction tuples for each pipe type"""
        if p_type == 1:
            return {(-1, 0), (0, -1)}  # top, left
        elif p_type == 2:
            return {(-1, 0), (0, 1)}   # top, right
        elif p_type == 3:
            return {(1, 0), (0, -1)}   # bottom, left
        elif p_type == 4:
            return {(1, 0), (0, 1)}    # bottom, right
        return set()

    def is_valid(grid_conf):
        """Check if the current grid configuration is fully filled and valid"""
        for i in range(n):
            for j in range(m):
                p = grid_conf[i][j]
                if p == 0:
                    return False  # Grid not fully filled

                dirs = get_directions(p)
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    # If direction points to border, that's fine
                    if ni < 0 or ni >= n or nj < 0 or nj >= m:
                        continue

                    neighbor = grid_conf[ni][nj]
                    if neighbor == 0:
                        return False  # Points to empty cell (not filled)

                    neighbor_dirs = get_directions(neighbor)
                    # Check if neighbor has the opposite direction
                    if (-dx, -dy) not in neighbor_dirs:
                        return False
        return True

    count = 0

    def backtrack(idx):
        nonlocal count
        if idx == n * m:
            if is_valid(grid):
                count = (count + 1) % MOD
            return

        i, j = idx // m, idx % m

        # Current cell was pre-filled
        if grid[i][j] != 0:
            backtrack(idx + 1)
        else:
            # Try all 4 pipe types
            for p in range(1, 5):
                grid[i][j] = p
                # Perform prune: check if this placement creates immediate conflicts
                valid_so_far = True
                for dx, dy in get_directions(p):
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m:
                        neighbor = grid[ni][nj]
                        # Points to empty cell - will be checked later
                        if neighbor == 0:
                            continue
                        # Check opposite direction constraint
                        neighbor_dirs = get_directions(neighbor)
                        if (-dx, -dy) not in neighbor_dirs:
                            valid_so_far = False
                            break

                if valid_so_far:
                    backtrack(idx + 1)
                grid[i][j] = 0

    backtrack(0)

    return str(count) + '\n'

