    index_counter = [0]
    stack = []
    lowlink = {}
    index = {}
    scc = {}
    scc_id = 0

    def scc_dfs(at):
        index[at] = index_counter[0]
        lowlink[at] = index_counter[0]
        index_counter[0] += 1
        stack.append(at)
        scc[at] = -1

        for to, length in adj[at]:
            if at not in index:
                scc_dfs(to)
                lowlink[at] = min(lowlink[at], lowlink[to])
            elif to in stack and to not in scc:
                lowlink[at] = min(lowlink[at], index[to])

        if lowlink[at] == index[at]:
            while stack:
                w = stack.pop()
                if w not in scc:
                    scc[w] = scc_id
                if w == at:
                    break
            scc_id += 1

    for i in range(1, n + 1):
        if i not in index:
            scc_dfs(i)

    # Compute cycle GCD for each SCC
    scc_gcd = {}

