def calc(n, fibs):
    """
    Calculate the number of decompositions of n into distinct Fibonacci numbers.

    Key insight: This relates to how we can form n using consecutive Fibonacci structure.
    For n not being a Fibonacci number: answer = 2^(k-2) where k is from consecutive fibs
    For n being a Fibonacci number: similar but with adjustment
    """
    if n <= 0:
        return 0

    # Find largest Fibonacci <= n
    lo = None
    for i, f in enumerate(fibs):
        if f <= n:
            lo = (i, f)
        else:
            break

    if lo is None or (n > fibs[-1] if fibs else True):
        # Handle edge cases
        if n <= fibs[-1]:
            idx = next(i for i, f in enumerate(fibs) if f == n)
            return calc_fib(idx)
        else:
            return 0

    idx, fib_val = lo

    if fib_val == n:
        return calc_fib(idx)
    else:
        # n is between fibs[idx] and fibs[idx+1]
        return 2 ** (idx - 2) if idx >= 2 else 1


def calc_fib(idx):
    """Calculate answer when n is exactly at Fibonacci index idx"""
    if idx < 2:
        return 1
    if idx == 2:  # fib=3
        return 2
    # General formula
    return 2 ** (idx - 1) if idx != 5 else 3


