def solution(m):
    n = len(m)

    # If empty or all empty, return 0 blocks
    if n == 0 or all(c == '_' for c in m):
        return '\n0\n'

    # Extract consecutive '#' block lengths from the mask
    p = []
    i = 0
    while i < n:
        if m[i] == '#':
            j = i
            while j < n and m[j] == '#':
                j += 1
            p.append(j - i)
            i = j
        else:
            i += 1

    k = len(p)
    if k == 0:
        return '\n0\n'

    L = sum(p)  # Total filled cells
    min_span = L + k - 1  # Minimum span = filled cells + gaps between blocks

    if n < min_span:
        return '-1\n'

    R = n - min_span  # Extra gaps to distribute

    # Precompute prefix sums for leftmost placements
    prefix_sum = [0] * k
    cum = 0
    for b in range(k):
        if b > 0:
            cum += p[b-1] + 1
        prefix_sum[b] = cum

    # Precompute suffix sums for rightmost placements
    suffix_sum = [0] * k
    cum2 = 0
    for b in range(k-1, -1, -1):
        if b < k - 1:
            cum2 += suffix_sum[b+1] + 1
        suffix_sum[b] = cum2

    # Verify mask consistency
    for i in range(n):
        fill_left = False
        # Check if position i is filled in leftmost arrangement
        for b in range(k):
            start = prefix_sum[b]
            end = start + p[b] - 1
            if start <= i <= end:
                fill_left = True
                break

        fill_right = False
        # Check if position i is filled in rightmost arrangement
        for b in range(k):
            start = n - suffix_sum[b] - 1
            end = start + p[b] - 1
            if start <= i <= end:
                fill_right = True
                break

        if m[i] == '#':
            # Must be filled in ALL arrangements (both extremes)
            if not fill_left or not fill_right:
                return '-1\n'
        elif m[i] == '_':
            # Must be empty in at least one arrangement
            if fill_left and fill_right:
                return '-1\n'

    return str(k) + '\n' + ' '.join(map(str, p)) + '\n'

