    for i in range(n):
        parts = lines[1 + i].split()
        ci.append(int(parts[0]))
        di.append(int(parts[1]))
        if i > 0:
            parent = int(parts[2]) - 1
            children[parent].append(i)

    # Tree DP: for each subtree compute best outcomes
    # Returns dict {k: min_cost}

    def compute_dp(u, parent_using_coupon):
        """
        u: current node
        parent_using_coupon: whether parent used coupon (determines if this can use coupon)
        Comment: The constraint is: to use coupon i, must use coupon xi.
        So if we use coupon at child, parent must have used coupon
        """
        if not children[u]:
            # Leaf node
            options = {0: 0}  # Don't buy
            if ci[u] <= b:
                options[1] = min(options.get(1, float('inf')), ci[u])  # Buy without coupon

            if parent_using_coupon:
                # Can optionally use coupon
                discount_price = ci[u] - di[u]
                if discount_price >= 0 and discount_price < ci[u]:
                    options[1] = min(options.get(1, float('inf')), discount_price)

            return options

        # Get children results
        child_opts = [compute_dp(c, parent_using_coupon) for c in children[u]]

        # Merge children
        merged = {0: 0}
        for child in child_opts:
            new_merged = {}
            for k1, c1 in merged.items():
                for k2, c2 in child.items():
                    nk = k1 + k2
                    cc = c1 + c2
                    if nk not in new_merged or new_merged[nk] > cc:
                        new_merged[nk] = cc
            merged = new_merged

        # Now add current node u
        result = {0: 0}  # Don't buy u

        if ci[u] <= b:
            # Can buy without coupon
            result[1] = result.get(1, float('inf')) + merged.get(0, 0)

            # Merge children with buying u
            for k in merged:
                new_k = k + 1
                new_cost = merged[k] + ci[u]
                if new_k not in result or result[new_k] > new_cost:
                    result[new_k] = new_cost

        if parent_using_coupon:
            discount_price = ci[u] - di[u]
            if discount_price < ci[u] and discount_price >= 0:
                # Buy with coupon
                new_result = {}
                for k, c in merged.items():
                    nk = k + 1
                    nc = c + discount_price
                    if nk not in new_result or new_result[nk] > nc:
                        new_result[nk] = nc

                for k, c in result.items():
                    if c <= b:  # Verify within budget
                        new_k = k
                        if c > new_result.get(new_k, float('inf')):
                            new_result[new_k] = c

                # Actually simpler:
                result = {k + 1: c + discount_price for k, c in merged.items()}
                for k, c in result.items():
                    if c in result.values():
                        result[k] = min(result.get(k, float('inf')), c)

        return result

    # For root, parent cannot use coupon (no parent)
    root_dp = compute_dp(0, False)

    ans = 0
    for k, cost in root_dp.items():
        if cost <= b:
            ans = max(ans, k)

    return str(ans)

